    "fr": "كَيْفَ حَالُك؟ – بِخَيْر، وَأَنْت؟",
    "de": "Wie geht es dir? – Gut, und dir?",
    "luecke": "كَيْفَ حَالُك",
    "gloss": "كَيْفَ حَال·ُك؟ – بِ·خَيْر، وَ·أَنْت؟ | wie Zustand·dein? – in·Gutes, und·du?",
    "umschrift": "kayfa ḥāluk? – bi-khayr, wa-anta?",
