    "fakt": "حَافَّةُ العَالَمِ جُرُفٌ صَخْرِيٌّ قُرْبَ الرِّيَاض. تَقِفُ عَلَى طَرَفِهِ وَلا تَرَى إِلَّا الصَّحْرَاءَ حَتَّى الأُفُق.",
    "fakt_de": "Die Kante der Welt ist eine Felsklippe nahe Riad. Man steht an ihrem Rand und sieht nur Wüste bis zum Horizont.",
